CREATE OR REPLACE FUNCTION public.pm_message_guard() RETURNS trigger LANGUAGE plpgsql SET search_path=public AS $$ DECLARE q public.pm_task_messages; p uuid; BEGIN IF TG_OP='UPDATE' THEN IF NEW.id<>OLD.id OR NEW.task_id<>OLD.task_id OR NEW.project_id<>OLD.project_id OR NEW.author_id<>OLD.author_id OR NEW.recipient_id IS DISTINCT FROM OLD.recipient_id OR NEW.kind<>OLD.kind OR NEW.reply_to_id IS DISTINCT FROM OLD.reply_to_id OR NEW.text<>OLD.text OR NEW.created_at<>OLD.created_at OR OLD.kind<>'mention' OR OLD.recipient_id<>auth.uid() OR NEW.seen_at IS NULL THEN RAISE EXCEPTION 'O histórico da conversa é imutável.'; END IF; NEW.seen_at:=COALESCE(OLD.seen_at,now()); RETURN NEW; END IF; SELECT project_id INTO p FROM public.pm_tasks WHERE id=NEW.task_id; IF p IS NULL OR p<>NEW.project_id OR NOT public.pm_can_edit(p) OR NEW.author_id<>auth.uid() OR NEW.seen_at IS NOT NULL THEN RAISE EXCEPTION 'Tarefa ou autor inválido.'; END IF; NEW.created_at:=now(); IF NEW.kind='answer' THEN PERFORM pg_advisory_xact_lock(hashtextextended(NEW.reply_to_id::text,0)); SELECT * INTO q FROM public.pm_task_messages WHERE id=NEW.reply_to_id; IF q.id IS NULL OR q.kind<>'question' OR q.task_id<>NEW.task_id OR q.recipient_id<>auth.uid() OR q.author_id=auth.uid() OR EXISTS(SELECT 1 FROM public.pm_task_messages WHERE reply_to_id=q.id) THEN RAISE EXCEPTION 'Somente o destinatário pode responder uma pergunta pendente desta tarefa.'; END IF; NEW.recipient_id:=q.author_id; ELSE IF NEW.reply_to_id IS NOT NULL OR NEW.recipient_id IS NULL OR NEW.recipient_id=auth.uid() OR NOT EXISTS(SELECT 1 FROM public.profiles WHERE id=NEW.recipient_id AND is_active AND deleted_at IS NULL) OR NOT private.has_app_access(NEW.recipient_id,'projects') OR (NOT EXISTS(SELECT 1 FROM public.pm_projects WHERE id=p AND manager_id=NEW.recipient_id) AND NOT EXISTS(SELECT 1 FROM public.pm_members WHERE project_id=p AND user_id=NEW.recipient_id)) THEN RAISE EXCEPTION 'Selecione outro participante autorizado do projeto.'; END IF; END IF; RETURN NEW; END $$; REVOKE ALL ON FUNCTION public.pm_message_guard() FROM PUBLIC,anon,authenticated;